package cn.workbench;

import org.springframework.stereotype.Service;
import java.time.LocalDate;
import java.util.*;
import static cn.workbench.Records.map;

@Service public class KeyWorkService {
 final Records records; final Policy policy; final TaskService tasks;
 public KeyWorkService(Records records,Policy policy,TaskService tasks){this.records=records;this.policy=policy;this.tasks=tasks;}
 @SuppressWarnings("unchecked") static Map<String,Object> data(Map<String,Object> task){return task.get("keyWorkData") instanceof Map<?,?> m?new LinkedHashMap<>((Map<String,Object>)m):map("enabled",false,"fields",List.of(),"values",Map.of(),"coordinationStatus","NONE","feedback","");}
 @SuppressWarnings("unchecked") static List<Map<String,Object>> fields(Object input){
  if(!(input instanceof List<?> list)||list.size()>30)throw TaskService.invalid("自定义字段最多30项");
  var result=new ArrayList<Map<String,Object>>();var ids=new HashSet<String>();
  for(Object item:list){if(!(item instanceof Map<?,?>))throw TaskService.invalid("字段配置无效");var field=(Map<String,Object>)item;String id=TaskService.text(field,"id",64),name=TaskService.text(field,"name",80),type=TaskService.text(field,"type",20);if(!id.matches("[A-Za-z0-9_-]+")||!ids.add(id)||!Set.of("TEXT","NUMBER","DATE","SELECT").contains(type))throw TaskService.invalid("字段编号或类型无效");if(!(field.get("required") instanceof Boolean required))throw TaskService.invalid("必填设置无效");var clean=map("id",id,"name",name,"type",type,"required",required);if(type.equals("SELECT")){if(!(field.get("options") instanceof List<?> options)||options.isEmpty()||options.size()>30)throw TaskService.invalid("请设置下拉选项");var choices=new ArrayList<String>();for(var o:options){if(!(o instanceof String s)||s.isBlank()||s.length()>100||choices.contains(s))throw TaskService.invalid("下拉选项无效或重复");choices.add(s);}clean.put("options",choices);}result.add(clean);}
  return result;
 }
 @SuppressWarnings("unchecked") static Map<String,Object> values(Map<String,Object> data){return data.get("values") instanceof Map<?,?> m?new LinkedHashMap<>((Map<String,Object>)m):new LinkedHashMap<>();}
 boolean manager(Policy.Actor a,Map<String,Object> t){return a.delegationId()==null&&(a.globalAdmin()||a.leader()&&Domain.companyAllowed(a.role(),a.company(),TaskService.integer(t,"companyId"))&&(a.role().equals("GROUP_LEADER")||TaskService.number(t,"creatorId")==a.uid()));}
 boolean editor(Policy.Actor a,Map<String,Object> t){if(manager(a,t))return true;if(a.delegationId()!=null||!Set.of("IN_PROGRESS","REWORK").contains(t.get("status")))return false;if(a.leader()&&Domain.companyAllowed(a.role(),a.company(),TaskService.integer(t,"companyId")))return true;if(!Objects.equals(a.company(),TaskService.integer(t,"companyId"))||!Objects.equals(a.dept(),TaskService.integer(t,"hostDeptId")))return false;return records.children(TaskService.number(t,"id"),"SUB_TASK").stream().filter(s->Boolean.TRUE.equals(s.get("isHost"))&&Set.of("IN_PROGRESS","REWORK").contains(s.get("status"))).anyMatch(s->{try{policy.subtask(a,s,true);return true;}catch(ApiException e){return false;}});}
 Map<String,Object> locked(Policy.Actor a,long id,Map<String,Object> input){policy.task(a,id);var t=records.lock(id);TaskService.version(t,input);if(Set.of("COMPLETED","CANCELLED").contains(t.get("status")))throw ApiException.conflict();return t;}
 void save(Policy.Actor a,Map<String,Object> task,Map<String,Object> before,Map<String,Object> after,String action){task.put("keyWorkData",after);records.save(task);records.create("KEY_WORK_HISTORY",TaskService.integer(task,"companyId"),a.dept(),TaskService.number(task,"id"),a.uid(),action,map("actorId",a.uid(),"before",before,"after",after));tasks.event(a,task,"KEY_WORK_"+action);}
 public Map<String,Object> configure(Policy.Actor a,long id,Map<String,Object> input){var t=locked(a,id,input);if(!manager(a,t))throw ApiException.denied();var before=data(t);var after=new LinkedHashMap<>(before);var next=fields(input.get("fields"));var old=fields(before.get("fields"));var vals=values(before);for(var field:next){String key=(String)field.get("id");var previous=old.stream().filter(f->key.equals(f.get("id"))).findFirst().orElse(null);if(previous!=null&&vals.containsKey(key)&&!Objects.equals(previous.get("type"),field.get("type")))throw TaskService.invalid("已有填写内容的字段不能更改类型");if("SELECT".equals(field.get("type"))&&vals.containsKey(key)&&!((List<?>)field.get("options")).contains(vals.get(key)))throw TaskService.invalid("已有填写内容不在下拉选项中");}var allowed=new HashSet<String>();next.forEach(f->allowed.add((String)f.get("id")));vals.keySet().retainAll(allowed);after.put("fields",next);after.put("values",vals);after.put("enabled",Boolean.TRUE.equals(input.get("keyWork")));save(a,t,before,after,"CONFIGURE");return t;}
 @SuppressWarnings("unchecked") public Map<String,Object> fill(Policy.Actor a,long id,Map<String,Object> input){var t=locked(a,id,input);if(!editor(a,t))throw ApiException.denied();var before=data(t);if(!(input.get("values") instanceof Map<?,?> raw))throw TaskService.invalid("填写内容无效");var supplied=(Map<String,Object>)raw;var result=new LinkedHashMap<String,Object>();var definitions=fields(before.get("fields"));var known=new HashSet<String>();for(var f:definitions){String key=(String)f.get("id"),type=(String)f.get("type");known.add(key);Object value=supplied.get(key);if(value==null||value instanceof String s&&s.isBlank()){if(Boolean.TRUE.equals(f.get("required")))throw TaskService.invalid(f.get("name")+"不能为空");continue;}switch(type){case "TEXT"->{if(!(value instanceof String s)||s.length()>4000)throw TaskService.invalid("文字内容无效");}case "NUMBER"->{if(!(value instanceof Number n)||!Double.isFinite(n.doubleValue()))throw TaskService.invalid("数字无效");}case "DATE"->{try{if(!(value instanceof String s))throw new IllegalArgumentException();LocalDate.parse(s);}catch(Exception e){throw TaskService.invalid("日期无效");}}case "SELECT"->{if(!((List<?>)f.get("options")).contains(value))throw TaskService.invalid("选项无效");}default->throw TaskService.invalid("类型无效");}result.put(key,value);}if(!known.containsAll(supplied.keySet()))throw TaskService.invalid("字段已变化，请刷新");var after=new LinkedHashMap<>(before);after.put("values",result);save(a,t,before,after,"FILL");return t;}
 public Map<String,Object> feedback(Policy.Actor a,long id,Map<String,Object> input){var t=locked(a,id,input);if(!manager(a,t))throw ApiException.denied();String status=TaskService.text(input,"coordinationStatus",20);if(!Set.of("NONE","PENDING","IN_PROGRESS","RESOLVED").contains(status))throw TaskService.invalid("协调状态无效");Object value=input.getOrDefault("feedback","");if(!(value instanceof String s)||s.length()>4000)throw TaskService.invalid("领导反馈无效");var before=data(t);var after=new LinkedHashMap<>(before);after.put("coordinationStatus",status);after.put("feedback",value);save(a,t,before,after,"FEEDBACK");return t;}
}
